def is_costas(p):
    n = len(p)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = p[j] - p[i]
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

def find_costas(n, fixed):
    from itertools import permutations
    for p in permutations(range(n)):
        # Check fixed values
        valid = True
        for idx, val in fixed.items():
            if p[idx] != val:
                valid = False
                break
        if not valid:
            continue
        if is_costas(p):
            return list(p)
    return None

print(find_costas(5, {2: 3}))
